          },
        ],
      },
    ],
    visualMap: {
      min: 1,
      max: 100,
      calculable: true,
      inRange: {
        color: ['#c0d5f0', '#1a4a92'],
      },
      textStyle: {
        color: '#000',
      },
    },
  };

  const chartInstance = echarts.init(document.getElementById('mapContainer'));
  chartInstance.setOption(option);
}
```

This code would initialize an ECharts map with the world map, and draw a circle (using the `effectScatter` series type) at given coordinates. You can customize the coordinates by changing the `value` field of the `data` array in the `series` object.

