import Foundation

class PomodoroTimer {
    private var timer: Timer?
    private var timeRemaining: TimeInterval

    init(duration: TimeInterval) {
        timeRemaining = duration
    }

    func start() {
        timer = Timer.scheduledTimer(withTimeInterval: 1, repeats: true) { _ in
            self.tick()
        }
    }

    func stop() {
        timer?.invalidate()
    }

    private func tick() {
        timeRemaining -= 1
        if timeRemaining <= 0 {
            stop()
            print("Time's up!")
